import { useState } from "react";
import { useResults } from "../context/ResultsContext";
import { useNavigate } from "react-router-dom";

export default function UploadResumes() {
  const { setResults } = useResults();
  const navigate = useNavigate();

  const [files, setFiles] = useState([]);
  const [links, setLinks] = useState([]);
  const [loading, setLoading] = useState(false);

  const handleFileChange = (e) => {
    const selected = Array.from(e.target.files);
    setFiles(selected);
    setLinks(selected.map(() => ""));
  };

  const handleLinkChange = (index, value) => {
    const updated = [...links];
    updated[index] = value;
    setLinks(updated);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const formData = new FormData();
    files.forEach((file) => formData.append("resumes", file));
    links.forEach((link) => formData.append("github_links", link));

    try {
      setLoading(true);
      const res = await fetch("http://localhost:5000/api/analyze", {
        method: "POST",
        body: formData,
      });

      const data = await res.json();
      setResults(data.results);
      navigate("/results");
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="page-wrapper">
      <div className="container-fluid px-5">
        <h2 className="page-title">Upload Resumes</h2>
        <p className="page-subtitle">
          Upload resumes with optional GitHub / portfolio links.
        </p>

        <div className="theme-card">
          <form onSubmit={handleSubmit}>
            {/* FILE UPLOAD */}
            <input
              type="file"
              id="resumeFiles"
              multiple
              accept=".pdf,.docx"
              style={{ display: "none" }}
              onChange={handleFileChange}
            />

            <label
              htmlFor="resumeFiles"
              className="theme-btn"
              style={{ cursor: "pointer" }}
            >
              Choose Resume Files
            </label>

            {files.length > 0 && (
              <div className="mt-3" style={{ color: "#bdbdbd" }}>
                {files.length} file(s) selected
              </div>
            )}

            {/* GITHUB / PORTFOLIO INPUTS (BIGGER UI) */}
            {files.map((file, i) => (
              <div key={i} className="mb-4 mt-4">
                <label style={{ color: "#bdbdbd" }}>
                  {file.name} — GitHub / Portfolio (optional)
                </label>

                <input
                  type="url"
                  className="theme-input mt-2"
                  placeholder="https://github.com/username or portfolio link"
                  value={links[i]}
                  onChange={(e) => handleLinkChange(i, e.target.value)}
                  style={{
                    width: "100%",
                    padding: "14px 16px",
                    fontSize: "15px",
                    borderRadius: "12px",
                  }}
                />
              </div>
            ))}

            {/* SUBMIT */}
            <div className="mt-4">
              <button className="theme-btn" type="submit" disabled={loading}>
                {loading ? "Analyzing..." : "Analyze Resumes"}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}
